bool read(const gfx::Control& c,double& n){const auto v=actuator_numeric(utf8(c.text()),-1,1);if(!v)return false;n=*v;return true;}
bool integer(const gfx::Control& c,unsigned& n){double v{};if(!read(c,v) || v<0 || v>UINT32_MAX || std::floor(v)!=v)return false;n=unsigned(v);return true;}
bool popup(const gfx::Control& c){uint32_t value{};ag_choice_open(c.handle(),&value);return value!=0;}
void choices(gfx::Control& c,const std::vector<std::wstring>& names,int selected){std::vector<const wchar_t*> p;for(const auto& n:names)p.push_back(n.c_str());c.replace(p,selected);}
template<class Callback>gfx::Control make(gfx::Context& context,void* parent,unsigned kind,unsigned id,const wchar_t* text,Callback callback,void* owner){ag_control_desc d{};d.kind=kind;d.id=id;d.text=text;d.bounds={0,0,1,1};d.minimum=0;d.maximum=1;return gfx::Control(context,parent,d,callback,owner);}
