std::vector<ActuatorInputChoice> actuator_input_choices(const RuntimeView& view,bool switches){std::vector<ActuatorInputChoice> out;for(const auto& device:view.devices)if(device.connected)for(const auto& c:device.controls)if(!c.relative && (switches?c.key.kind==ControlKind::button:c.key.kind==ControlKind::axis)){MotorFeedbackDefinition f;f.kind=MotorPositionSource::analogue;auto p=button_source(device,c);f.input_profile=profile_encode(p);out.push_back({std::move(f),wide(device.identity.name+" / "+device.identity.serial+" / "+c.name)});}return out;}
void __cdecl StepperPanel::event(void* p,std::uint32_t id,std::uint32_t kind,double value)noexcept{auto& s=*static_cast<StepperPanel*>(p);if(s.binding_)return;try{if(kind==AG_BUTTON_CANCEL){s.held_=false;s.runtime_->steppers().hold(s.selected_);return;}if(kind==AG_TEXT_CHANGED){s.edited_=true;return;}if(kind==AG_CLICK || kind==AG_VALUE_CHANGED || kind==AG_DROPDOWN_CHANGED || kind==AG_FOCUS_LOST || kind==AG_NAVIGATE || kind==AG_BUTTON_PRESS || kind==AG_BUTTON_RELEASE){if(s.events_.size()>=64){s.hide();return;}s.events_.push_back({id,kind,value});ag_window_post(s.owner_->handle(),dispatch_id);}}catch(...){s.hide();}}
