    for(unsigned n=0;n<count;++n){const bool choice=n==slot || n==device || n==mode || n==feedback;const bool button=n>=inspect && n!=target;const auto type=choice?AG_CHOICE:button?AG_BUTTON:n==invert?AG_CHECKBOX:AG_EDIT;controls_[n]=make(c,pane_.hwnd(),type,n+1,button?captions[n]:n==invert?captions[n]:L"",event,this);labels_[n]=make(c,pane_.hwnd(),AG_LABEL,0,button || n==invert?L"":captions[n],event,this);unsigned flags=AG_CONTROL_NAV_TAB;if(type==AG_EDIT)flags|=AG_CONTROL_NOTIFY_TEXT|AG_CONTROL_NOTIFY_FOCUS|AG_CONTROL_NAV_ACTIVATE;if(choice)flags|=AG_CONTROL_NOTIFY_DROPDOWN;if(n==back || n==forward)flags|=AG_CONTROL_NOTIFY_BUTTON_EDGES;ag_control_events(controls_[n].handle(),flags);}
    for(unsigned n=0;n<10;++n)controls_[slot].add((L"Motor "+std::to_wstring(n+20)).c_str());controls_[mode].add(L"STEP — generated microsteps");controls_[mode].add(L"RUN — measured-feedback position loop");controls_[device].add(L"Unassigned");controls_[feedback].add(L"Unassigned");controls_[target].text(L"0");bind();layout();ag_visible(pane_.handle(),0);
