void StepperPanel::bind(){binding_=true;const auto v=runtime_->steppers().snapshot(selected_);const auto& d=v.draft;controls_[slot].value(selected_);controls_[name].text(wide(d.name).c_str());controls_[mode].value(d.run_mode?1:0);controls_[invert].value(d.feedback.inverted?1:0);
    for(const auto& [f,value]:std::initializer_list<std::pair<Field,double>>{{current,d.current},{holding,d.holding_current},{velocity,d.velocity},{acceleration,d.acceleration},{steps,d.full_steps},{gearing,d.gearing},{kp,d.kp},{ki,d.ki},{kd,d.kd},{vff,d.vff},{aff,d.aff},{feedback_velocity,d.feedback_velocity},{feedback_acceleration,d.feedback_acceleration},{backlash,d.backlash},{interval,d.interval_ms},{failsafe,d.failsafe_ms}})controls_[f].text(number(value).c_str());
    const auto at=std::find(devices_.begin(),devices_.end(),d.address);controls_[device].value(at==devices_.end()?0:double(at-devices_.begin()+1));unsigned selected{};for(unsigned n=0;n<feedback_.size();++n)if(feedback_[n].input.input_profile==d.feedback.input_profile)selected=n+1;controls_[feedback].value(selected);for(auto f:{feedback,invert,kp,ki,kd,vff,aff,feedback_velocity,feedback_acceleration,backlash})controls_[f].enabled(d.run_mode);labels_[target].text(d.run_mode?L"Target (sensor counts)":L"Target (microsteps)");displayed_=d;edited_=false;binding_=false;
}
bool StepperPanel::commit(){if(!edited_)return true;auto d=runtime_->steppers().snapshot(selected_).draft;d.name=utf8(controls_[name].text());d.run_mode=controls_[mode].value()!=0;d.feedback.inverted=controls_[invert].value()!=0;bool ok=true;
    for(const auto& [f,value]:std::initializer_list<std::pair<Field,double*>>{{current,&d.current},{holding,&d.holding_current},{velocity,&d.velocity},{acceleration,&d.acceleration},{steps,&d.full_steps},{gearing,&d.gearing},{kp,&d.kp},{ki,&d.ki},{kd,&d.kd},{vff,&d.vff},{aff,&d.aff},{feedback_velocity,&d.feedback_velocity},{feedback_acceleration,&d.feedback_acceleration},{backlash,&d.backlash}})ok=read(controls_[f],*value)&&ok;ok=integer(controls_[interval],d.interval_ms)&&integer(controls_[failsafe],d.failsafe_ms)&&ok;std::string error;if(!ok || !runtime_->steppers().edit(selected_,d,error)){problem_=ok?wide(error):L"Enter finite settings and whole-number intervals";return false;}edited_=false;problem_.clear();displayed_=d;return true;
}
void StepperPanel::choices(const RuntimeView& view){std::uint64_t signature=view.phidgets.revision+view.profile_revision;for(const auto& dev:view.devices)signature=signature*1099511628211ull+dev.generation+dev.controls.size()+unsigned(dev.connected);if(inventory_==signature || popup(controls_[device]) || popup(controls_[feedback]))return;binding_=true;devices_.clear();std::vector<std::wstring> names{L"Unassigned"};const auto saved=runtime_->steppers().snapshot(selected_).draft;
    for(const auto& c:view.phidgets.channels)if(c.channel_class==PHIDCHCLASS_STEPPER && c.address.model==PHIDID_STC1005){devices_.push_back(c.address);names.push_back(wide(std::to_string(c.address.serial)+" / VINT "+std::to_string(c.address.hub_port)+" / channel "+std::to_string(c.address.channel)+(c.address.remote?" / "+c.address.server:" / USB")));}if(saved.address.assigned() && std::find(devices_.begin(),devices_.end(),saved.address)==devices_.end()){devices_.push_back(saved.address);names.push_back(wide(saved.address.device+" (unavailable)"));}const auto at=std::find(devices_.begin(),devices_.end(),saved.address);hwio::choices(controls_[device],names,at==devices_.end()?0:int(at-devices_.begin())+1);
    feedback_=actuator_input_choices(view,false);names={L"Unassigned"};unsigned selected{};for(unsigned n=0;n<feedback_.size();++n){names.push_back(feedback_[n].name);if(feedback_[n].input.input_profile==saved.feedback.input_profile)selected=n+1;}if(!saved.feedback.input_profile.empty() && !selected){feedback_.push_back({saved.feedback,L"Saved sensor (unavailable)"});names.push_back(L"Saved sensor (unavailable)");selected=unsigned(feedback_.size());}hwio::choices(controls_[feedback],names,int(selected));inventory_=signature;binding_=false;
}
void StepperPanel::layout(){if(!pane_.handle())return;auto batch=pane_.update_scope();const float width=std::max(320.f,float(width_))-24;float y=8;status_.bounds({12,y,width,y+62});y+=66;auto row=[&](std::initializer_list<Field> fs){const float w=width/float(fs.size());float h=20;for(auto f:fs)h=std::max(h,labels_[f].text_extent(w-8).y+2);unsigned n{};for(auto f:fs){const float x=12+w*float(n++);labels_[f].bounds({x,y,x+w-8,y+h});controls_[f].bounds({x,y+h,x+w-8,y+h+30});}y+=h+38;};row({slot,device});row({name,mode});row({feedback,invert});row({current,holding});row({velocity,acceleration});row({steps,gearing});row({kp,ki,kd});row({vff,aff});row({feedback_velocity,feedback_acceleration});row({backlash});row({interval,failsafe});row({inspect,stop});row({back,forward});row({target,move,zero});row({save,revert,clear});pane_.extent(y);}
void StepperPanel::arrange(int x,int y,int w,int h,bool shown){const bool resize=w!=width_ || h!=height_;if(visible_ && !shown)hide();if(!visible_ && shown){runtime_->actuators().bench({ActuatorKind::stepper,selected_},true);runtime_->steppers().bench(int(selected_));}visible_=shown;width_=w;height_=h;pane_.bounds({float(x),float(y),float(x+w),float(y+h)});ag_visible(pane_.handle(),shown);if(resize)layout();}
void StepperPanel::refresh(const RuntimeView& view){choices(view);if(!visible_)return;const auto v=runtime_->steppers().snapshot(selected_);bool open=false;for(const auto f:{slot,device,mode,feedback})open|=popup(controls_[f]);if(!edited_ && !open && (!displayed_ || *displayed_!=v.draft))bind();const auto text=problem_.empty()?wide(v.status+(v.dirty?" [unsaved]":"")+"\n"+(v.draft.run_mode?"Measured sensor position: ":"Generated microstep position: "))+number(v.live.position):problem_;if(status_.text()!=text)status_.text(text.c_str());}
void StepperPanel::tick(){if(!visible_)return;if(!IsWindowVisible(static_cast<HWND>(owner_->hwnd())) || IsIconic(static_cast<HWND>(owner_->hwnd()))){hide();return;}if(held_)runtime_->steppers().drive(selected_,direction_);}
void StepperPanel::dispatch(){while(!events_.empty()){const auto e=events_.front();events_.pop_front();if(!e.id || e.id>count)continue;const auto f=Field(e.id-1);if(e.kind==AG_BUTTON_RELEASE){held_=false;runtime_->steppers().hold(selected_);continue;}if(e.kind==AG_BUTTON_PRESS && (f==back || f==forward)){if(commit()){held_=true;direction_=f==back?-1:1;runtime_->steppers().drive(selected_,direction_,true);}continue;}
        if(f==slot || f==device || f==mode || f==feedback){if(popup(controls_[f]) || (e.kind!=AG_VALUE_CHANGED && e.kind!=AG_DROPDOWN_CHANGED))continue;if(f==slot){if(!commit())continue;runtime_->steppers().bench(-1);runtime_->actuators().bench({ActuatorKind::stepper,selected_},false);selected_=std::min(unsigned(controls_[slot].value()),9u);runtime_->actuators().bench({ActuatorKind::stepper,selected_},true);runtime_->steppers().bench(int(selected_));inventory_=UINT64_MAX;bind();}else{if(!commit())continue;auto d=runtime_->steppers().snapshot(selected_).draft;const unsigned index=unsigned(controls_[f].value());if(f==device)d.address=index && index<=devices_.size()?devices_[index-1]:MotorDeviceAddress{};if(f==feedback)d.feedback=index && index<=feedback_.size()?feedback_[index-1].input:MotorFeedbackDefinition{};if(f==mode)d.run_mode=index!=0;std::string error;if(!runtime_->steppers().edit(selected_,d,error))problem_=wide(error);else{displayed_.reset();bind();}}continue;}
        if(e.kind==AG_FOCUS_LOST || (e.kind==AG_NAVIGATE && int(e.value)==AG_NAV_ENTER)){commit();continue;}if(f==invert && e.kind==AG_VALUE_CHANGED){edited_=true;commit();continue;}if(e.kind!=AG_CLICK)continue;
        if(f==stop){held_=false;runtime_->steppers().stop(selected_);}else if(f==clear){runtime_->steppers().clear(selected_);displayed_.reset();}else if(f==revert){runtime_->steppers().revert(selected_);edited_=false;displayed_.reset();}else if(commit()){if(f==inspect)runtime_->steppers().inspect(selected_);if(f==move){double value{};std::string error;if(!read(controls_[target],value))problem_=L"Enter a finite target position";else if(!runtime_->steppers().move_to(selected_,value,error))problem_=wide(error);else problem_.clear();}if(f==zero){std::string error;if(!runtime_->steppers().zero(selected_,error))problem_=wide(error);else problem_.clear();}if(f==save){std::string error;if(!runtime_->steppers().save(selected_,error))problem_=wide(error);}}
    }}
void StepperPanel::hide(){held_=false;events_.clear();if(runtime_ && visible_){runtime_->steppers().bench(-1);runtime_->actuators().bench({ActuatorKind::stepper,selected_},false);}visible_=false;}
