    for(unsigned n=0;n<count;++n){const bool choice=n==kind || n==output || n==source || n==sw1 || n==sw2 || n==pot || n==search_direction || n==rotary || n==startup || n==direction;const bool check=n==demand || n==enabled || n==automatic || n==active1 || n==active2 || n==two || n==invert;const bool button=n==capture_min || n==capture_max || n>=apply;const auto type=choice?AG_CHOICE:check?AG_CHECKBOX:button?AG_BUTTON:AG_EDIT;controls_[n]=make(c,form_.hwnd(),type,1000+n,check || button?captions[n]:L"",event,this);labels_[n]=make(c,form_.hwnd(),AG_LABEL,0,check || button?L"":captions[n],event,this);unsigned flags=AG_CONTROL_NAV_TAB;if(type==AG_EDIT)flags|=AG_CONTROL_NOTIFY_TEXT|AG_CONTROL_NOTIFY_FOCUS|AG_CONTROL_NAV_ACTIVATE;if(choice)flags|=AG_CONTROL_NOTIFY_DROPDOWN;ag_control_events(controls_[n].handle(),flags);}
