void ActuatorPanel::navigate(int group,int output){
    if(selected_>=0 && !axis_mode_){ag_panel_scroll_get(form_.handle(),&scroll_[unsigned(selected_)]);if(manual_home_ && runtime_->actuators().snapshot(unsigned(selected_)).phase==ActuatorPhase::homing)runtime_->actuators().stop(unsigned(selected_));}
    motors_->hide();group_=group;output_=output;selected_=-1;axis_mode_=false;status_.text(L"");manual_home_=false;edited_=false;problem_.clear();input_revision_=UINT64_MAX;
    if(output>=0){const auto defs=runtime_->actuators().definitions();for(unsigned n=0;n<actuator_mapping_slots;++n)if(defs[n].analogue_output==unsigned(output)){selected_=int(n);break;}
        if(group==1){axis_mode_=selected_<0;for(const auto& d:runtime_->motor_mappings().definitions())if(d.analogue_output==unsigned(output))axis_mode_=true;}
        if(selected_<0)for(unsigned n=unsigned(group)*20;n<unsigned(group+1)*20;++n)if(!defs[n].enabled && defs[n].analogue_output==UINT_MAX){selected_=int(n);break;}
        if(selected_>=0){draft_=defs[unsigned(selected_)];draft_.calibration=ActuatorCalibration(group_);draft_.analogue_output=unsigned(output);draft_.home.rotation=group_==2;if(group_==2)draft_.home.two_switches=false;bind();}
        if(axis_mode_)motors_->select_output(output);
    }
    binding_=true;mode_.value(axis_mode_?0:1);binding_=false;layout();if(selected_>=0 && !axis_mode_)ag_panel_scroll_set(form_.handle(),scroll_[unsigned(selected_)]);
}
