    for(const auto& [f,value]:std::initializer_list<std::pair<Field,bool>>{{demand,d.source.demand},{enabled,d.enabled},{automatic,d.auto_home},{active1,d.active_high[0]},{active2,d.active_high[1]},{two,d.home.two_switches},{invert,d.potentiometer.inverted}})controls_[f].value(value?1:0);controls_[search_direction].value(d.home.direction<0?1:0);controls_[direction].value(d.direction<0?1:0);controls_[rotary].value(unsigned(d.rotary));controls_[startup].value(unsigned(d.startup));displayed_=d;edited_=false;binding_=false;choices();
