    for(unsigned n=0;n<count;++n){ag_visible(controls_[n].handle(),0);ag_visible(labels_[n].handle(),0);}float y=8;auto row=[&](std::initializer_list<Field> fs){const float w=width/float(fs.size());float h=20;for(auto f:fs)h=std::max(h,labels_[f].text_extent(w-8).y+2);unsigned i{};for(auto f:fs){const float x=12+w*float(i++);ag_visible(controls_[f].handle(),1);ag_visible(labels_[f].handle(),1);labels_[f].bounds({x,y,x+w-8,y+h});controls_[f].bounds({x,y+h,x+w-8,y+h+30});}y+=h+38;};
    row({name});row({kind,output});row({source});row({record,field,fields});row({unit,scale,offset});row({source_min,source_max});row({power,power_mask});row({demand});row({enabled,automatic});
    if(group_==1){row({pot,invert});row({sensor_min,sensor_max});row({command_min,command_max});row({capture_min,capture_max});}
