void ActuatorPanel::arrange(int x,int y,int w,int h,bool shown){if(visible_ && !shown)hide();visible_=shown;const bool resized=width_!=w || height_!=h;width_=w;height_=h;pane_.bounds({float(x),float(y),float(x+w),float(y+h)});ag_visible(pane_.handle(),shown);if(resized)layout();}
