    const auto v=runtime_->actuators().snapshot(unsigned(selected_));if(manual_home_ && v.phase!=ActuatorPhase::homing && !v.reset_pending)manual_home_=false;const auto text=problem_.empty()?wide(v.status)+L"\nPosition: "+number(v.position)+L" / target: "+number(v.target)+(edited_?L" [unapplied edits]":L""):problem_;if(status_.text()!=text)status_.text(text.c_str());
