        if(e.kind==AG_VALUE_CHANGED){edited_=true;commit();continue;}if(e.kind==AG_FOCUS_LOST || (e.kind==AG_NAVIGATE && int(e.value)==AG_NAV_ENTER)){commit();continue;}if(e.kind!=AG_CLICK)continue;
